// DimAgent — generated by src/powerbi/build_assets.py from DimAgent.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "DimAgent.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"agent_id", type text},
        {"agent_name", type text},
        {"team", type text},
        {"department_id", type text},
        {"hire_date", type date},
        {"experience_level", type text},
        {"employment_status", type text},
        {"shift", type text},
        {"location", type text},
        {"department_name", type text}
    }, "en-US")
in
    Typed
